    "language": "python",
    "description": "Exports ChatGroq factory and error classification helpers.",
    "content": "\"\"\"LLM integration package powered by Groq and LangChain.\"\"\"\n\nfrom llm.groq_model import (\n    GroqAPIError,\n    GroqConfigurationError,\n    classify_groq_error,\n    get_chat_groq,\n)\n\n__all__ = [\n    \"GroqAPIError\",\n    \"GroqConfigurationError\",\n    \"classify_groq_error\",\n    \"get_chat_groq\",\n]\n"
