    "path": "genai-chatbot/rag/text_splitter.py",
    "relPath": "rag/text_splitter.py",
    "folder": "rag",
    "language": "python",
    "description": "Splits extracted documents into overlapping chunks via RecursiveCharacterTextSplitter.",
    "content": "\"\"\"Document chunking using LangChain RecursiveCharacterTextSplitter.\"\"\"\n\nfrom typing import List, Optional\n\nfrom langchain_core.documents import Document\nfrom langchain_text_splitters import RecursiveCharacterTextSplitter\n\nfrom config.settings import settings\n\n\ndef split_documents(\n    documents: List[Document],\n    chunk_size: Optional[int] = None,\n    chunk_overlap: Optional[int] = None,\n) -> List[Document]:\n    \"\"\"Split loaded documents into overlapping semantic chunks while preserving metadata.\"\"\"\n    if not documents:\n        return []\n\n    splitter = RecursiveCharacterTextSplitter(\n        chunk_size=chunk_size or settings.chunk_size,\n        chunk_overlap=chunk_overlap or settings.chunk_overlap,\n        separators=[\"\\n\\n\", \"\\n\", \". \", \" \", \"\"],\n        length_function=len,\n    )\n\n    chunks = splitter.split_documents(documents)\n    for idx, chunk in enumerate(chunks):\n        chunk.metadata[\"chunk_index\"] = idx\n\n    return chunks\n"
