    "language": "python",
    "description": "Exports ChatSessionManager.",
    "content": "\"\"\"Conversational memory and persistent session history package.\"\"\"\n\nfrom memory.chat_history import ChatSessionManager\n\n__all__ = [\"ChatSessionManager\"]\n"
