    "description": "Exports validation, export, and streaming helpers.",
    "content": "\"\"\"Utility helpers and streaming adapters.\"\"\"\n\nfrom utils.helpers import (\n    export_chat_as_json,\n    export_chat_as_markdown,\n    format_timestamp_short,\n    validate_user_input,\n)\nfrom utils.streaming import extract_token_text, stream_langchain_chain, stream_text_smoothly\n\n__all__ = [\n    \"export_chat_as_json\",\n    \"export_chat_as_markdown\",\n    \"extract_token_text\",\n    \"format_timestamp_short\",\n    \"stream_langchain_chain\",\n    \"stream_text_smoothly\",\n    \"validate_user_input\",\n]\n"
